import type { Metadata } from "next";
import { BRAND, SITE_URL } from "@/lib/contact";

/** The card image — 1200×630, generated by the `app/og/route.tsx` route. */
export const OG_IMAGE_SIZE = { width: 1200, height: 630 };
export const OG_IMAGE_ALT = `${BRAND} — fizjoterapia, masaż i trening w Libiążu`;

/** A fresh object on every call — Next's metadata resolver consumes it. */
export const ogImage = () => ({
  url: `${SITE_URL}/og`,
  ...OG_IMAGE_SIZE,
  alt: OG_IMAGE_ALT,
});

/**
 * A subpage's metadata: title, description, canonical and the social card (OG + X).
 *
 * Next merges metadata SHALLOWLY — the `openGraph` object from page.tsx replaces the
 * layout's entirely, so every subpage must give the full set of fields. Hence this helper:
 * one source of the card's shape. The title in `<title>` gets the "… | Anova Studio"
 * template from the layout — for OG it has to be added by hand, because the template
 * covers only `title`.
 */
export function pageMetadata({
  title,
  description,
  path,
}: {
  title: string;
  description: string;
  /** The path from the root, e.g. "/oferta" — expanded with the domain through metadataBase. */
  path: string;
}): Metadata {
  const fullTitle = `${title} | ${BRAND}`;

  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: BRAND,
      locale: "pl_PL",
      url: path,
      title: fullTitle,
      description,
      images: [ogImage()],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [ogImage()],
    },
  };
}
